package adminui

const editorHTML = `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Draft.Snapshot.Canon.Name}} · Canon Cockpit</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f1ea;color:#171717;font:14px/1.5 Arial,sans-serif}header,main{max-width:1200px;margin:auto;padding:24px}header{border-bottom:1px solid #d8d3c9}h1{font:42px Georgia,serif}h2{font:26px Georgia,serif;margin-top:32px}.muted{color:#625e58}.error{color:#84271f;border:1px solid #a03027;padding:12px}.success{border:1px solid #49644a;padding:12px}a{color:inherit}input,select,textarea,button{font:inherit;border:1px solid #b9b4ab;background:#fbfaf7;padding:8px;max-width:100%}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}label{display:block;margin:12px 0}textarea{width:100%;min-height:280px;font:12px/1.5 monospace}table{border-collapse:collapse;width:100%}th,td{padding:10px;border-bottom:1px solid #d8d3c9;text-align:left;vertical-align:top}.table{overflow:auto}td input{width:110px}td .title{width:210px}details{border-top:1px solid #d8d3c9;padding:16px 0;margin-top:18px}summary{cursor:pointer;font-size:18px}.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center}form{margin:12px 0}.rank{width:65px}code{font-size:12px}:focus-visible{outline:2px solid #a03027;outline-offset:2px}.badge{font-size:11px;text-transform:uppercase;color:#625e58}
</style></head><body><header><a href="/canons">← Sammlungen</a> · reel canon. COCKPIT</header><main><h1>{{.Draft.Snapshot.Canon.Name}}</h1><p class="muted">Entwurf bearbeiten, Änderungen prüfen und anschließend veröffentlichen. Gespeicherte Entwürfe verändern den öffentlichen Katalog nicht.</p>
{{if .Message}}<p class="success" role="status">{{.Message}}</p>{{end}}
<p>Basis-Edition: {{.Draft.BaseEdition}} · Entwurf-Version: {{.Draft.Revision}} · {{len .Draft.Snapshot.Entries}} Filme</p>
{{if .Validation}}<p class="error" role="alert">Noch nicht veröffentlichbar: {{.Validation}}</p>{{else}}<p class="success">Validierung erfolgreich: vollständige, eindeutige Filmliste.</p>{{end}}
{{range .Draft.Conflicts}}<p class="error">Quellenkonflikt: {{.}}</p>{{end}}
<details open><summary>Sammlung gestalten</summary>
<form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/presentation">
<input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Draft.Revision}}"><input type="hidden" name="base" value="{{.Draft.BaseEdition}}">
<label>Sammlungsname <input name="name" value="{{.Draft.Snapshot.Canon.Name}}" required></label>
<label>Beschreibung <input name="description" value="{{.Draft.Snapshot.Canon.Description}}" style="width:100%"></label>
<label>Position in der Übersicht <input name="position" type="number" min="0" value="{{.Draft.Snapshot.Canon.Presentation.Position}}" required></label>
<p class="muted">Kleinere Positionen erscheinen zuerst. Bei gleicher Position entscheidet der Name.</p>
<label>Poster <input name="posterUrl" list="collection-posters" value="{{.Draft.Snapshot.Canon.Presentation.PosterURL}}" style="width:100%" required></label>
<datalist id="collection-posters"><option value="/artwork/imdb-top-250.svg">IMDb Top 250 · Editorial</option><option value="/artwork/halloween-top-100.svg">Halloween Top 100 · Editorial</option><option value="/artwork/oscar-best-picture.svg">Oscar · Bester Film · Editorial</option><option value="/artwork/imdb-top-250-filmwelten-editorial.png">IMDb Top 250 · Filmwelten (alt)</option><option value="/artwork/collection-03-filmwelten.png">Filmwelten ohne Titel</option><option value="/artwork/collection-01-filmrolle.png">Filmrolle</option><option value="/artwork/collection-02-kinosaal.png">Kinosaal</option></datalist>
<p class="muted">Vorhandenes Poster auswählen oder eine HTTPS-Bildadresse eintragen.</p>
<label><input type="checkbox" name="titleEmbedded" value="true" {{if .Draft.Snapshot.Canon.Presentation.TitleEmbedded}}checked{{end}}> Titel ist bereits im Poster enthalten</label>
<p class="muted">Bei einem neuen Namen auch das Poster wechseln oder den eingebetteten Titel ausschalten. Bildschrift wird nicht automatisch geändert.</p>
<label>Änderungsgrund <input name="reason" value="{{.Draft.Reason}}" required></label><button>Darstellung speichern</button>
</form><p class="muted">Der PosterBadge zeigt den persönlichen Fortschritt, z. B. 50/250. Das Poster wird entsprechend von unten nach oben farbig. Darstellung und Name werden gemeinsam mit der geprüften Edition veröffentlicht.</p>
</details>
<details open><summary>Filmliste und manuelle Änderungen</summary><label>Filme suchen <input id="filter" type="search" placeholder="Titel, Jahr oder IMDb ID"></label>
<div class="table"><table><thead><tr><th>Rang</th><th>Titel / Jahr</th><th>IMDb / TMDb</th><th>Herkunft / Metadaten</th><th>Entwurf bearbeiten</th></tr></thead><tbody id="films">
{{range $index,$entry:=.Draft.Snapshot.Entries}}{{$meta:=index $.Metadata $entry.IMDbID}}<tr><td><input form="film-{{$index}}" class="rank" type="number" min="1" name="position" aria-label="Rang {{$entry.IMDbID}}" value="{{$entry.Position}}" required></td><td><input form="film-{{$index}}" class="title" name="title" aria-label="Titel {{$entry.IMDbID}}" value="{{$entry.SourceTitle}}" required><br><input form="film-{{$index}}" type="number" name="year" aria-label="Jahr {{$entry.IMDbID}}" value="{{if $entry.ReleaseYear}}{{$entry.ReleaseYear}}{{end}}" min="1888" max="2100"></td><td><code>{{$entry.IMDbID}}</code><br>TMDb: {{if gt $entry.TMDbID 0}}{{$entry.TMDbID}}{{else if $meta.TMDbID.Valid}}{{$meta.TMDbID.Int64}}{{else}}—{{end}}<br><input form="film-{{$index}}" name="tmdbId" type="number" min="1" aria-label="Korrektur TMDb ID für Rang {{$entry.Position}}" placeholder="TMDb-ID korrigieren" value="{{if gt $entry.TMDbID 0}}{{$entry.TMDbID}}{{end}}"></td><td><span class="badge">{{index $.Origins $entry.IMDbID}}</span>{{if $meta.Error.Valid}}<p class="error">{{$meta.Error.String}}</p>{{end}}</td><td><form id="film-{{$index}}" method="post" action="/canons/{{$.Draft.Snapshot.Canon.Slug}}/entry"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="revision" value="{{$.Draft.Revision}}"><input type="hidden" name="base" value="{{$.Draft.BaseEdition}}"><input type="hidden" name="imdbId" value="{{$entry.IMDbID}}"><input type="hidden" name="originalPosition" value="{{$entry.Position}}"><input name="reason" aria-label="Grund {{$entry.IMDbID}}" placeholder="Änderungsgrund" value="{{$.Draft.Reason}}" required><br><button name="action" value="save">Ändern</button> <button name="action" value="remove" formnovalidate>Entfernen</button></form></td></tr>{{end}}
</tbody></table></div><form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/entry"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Draft.Revision}}"><input type="hidden" name="base" value="{{.Draft.BaseEdition}}"><h3>Film hinzufügen</h3><div class="actions"><input name="imdbId" aria-label="Neue IMDb ID (optional)" placeholder="IMDb-ID optional" pattern="tt[0-9]{7,10}"><input name="tmdbId" aria-label="Neue TMDb ID (optional)" type="number" min="1" placeholder="TMDb-ID optional"><input name="title" aria-label="Neuer Titel" placeholder="Titel für automatische Suche" required><input name="position" aria-label="Neuer Rang" type="number" min="1" placeholder="Rang" required><input name="year" aria-label="Neues Jahr" type="number" min="1888" max="2100" placeholder="Jahr"><input name="reason" aria-label="Grund für neuen Film" placeholder="Änderungsgrund" required><button>Zum Entwurf hinzufügen</button></div><p class="muted">IMDb-ID genügt. Ohne ID wird der exakte Titel mit optionalem Jahr bei TMDb gesucht. Bei mehreren Treffern eine TMDb-ID angeben.</p></form></details>
<details><summary>JSON-Entwurf bearbeiten</summary><form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/draft"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Draft.Revision}}"><input type="hidden" name="base" value="{{.Draft.BaseEdition}}"><label for="snapshot">Normalisierter Snapshot</label><textarea id="snapshot" name="snapshot" spellcheck="false">{{.JSON}}</textarea><label>Änderungsgrund <input name="reason" value="{{.Draft.Reason}}" required></label><button formaction="/canons/{{.Draft.Snapshot.Canon.Slug}}/resolve">Titel und IDs mit TMDb auflösen</button> <button>Entwurf speichern</button></form><p class="muted">Titel-only Einträge lassen sich hier gezielt auflösen. Mehrdeutige Titel zeigen Kandidaten samt TMDb-ID; unvollständige Entwürfe können weiterhin gespeichert werden.</p></details>
<details><summary>JSON / CSV importieren und exportieren</summary><form method="post" enctype="multipart/form-data" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/import"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Draft.Revision}}"><input type="hidden" name="base" value="{{.Draft.BaseEdition}}"><label>Datei (maximal 2 MB) <input name="file" type="file" accept=".json,.csv" required></label><label>Importgrund <input name="reason" required></label><button>Als Entwurf importieren</button></form><p>CSV-Kopf: <code>position,imdbId,tmdbId,sourceTitle,releaseYear,imdbRating</code>. IMDb-ID und TMDb-ID können leer bleiben; TMDb-ID überschreibt die automatische Titelsuche. Mehrdeutige Treffer bitte anhand der Fehlerkandidaten manuell eintragen.</p><div class="actions"><a href="/canons/{{.Draft.Snapshot.Canon.Slug}}/export">JSON exportieren</a><a href="/canons/{{.Draft.Snapshot.Canon.Slug}}/export?format=csv">CSV exportieren</a></div></details>
<details><summary>Aktive manuelle Änderungen</summary>{{range .Overrides}}<form method="post" action="/canons/{{$.Draft.Snapshot.Canon.Slug}}/override"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="revision" value="{{$.Draft.Revision}}"><input type="hidden" name="base" value="{{$.Draft.BaseEdition}}"><input type="hidden" name="imdbId" value="{{.IMDbID}}"><p>{{.IMDbID}} · {{.Kind}} · {{.Reason}}</p><label>Grund <input name="reason" required></label><button>Eintrag im Entwurf auf Quelle zurücksetzen</button></form>{{else}}<p>Keine aktiven manuellen Änderungen.</p>{{end}}</details><h2>Änderungsvorschau</h2>{{if .Changes}}<div class="table"><table><thead><tr><th>IMDb ID</th><th>Änderung</th><th>Vorher</th><th>Nachher</th></tr></thead><tbody>{{range .Changes}}<tr><td>{{.IMDbID}}</td><td>{{.Kind}}</td><td>{{.Before}}</td><td>{{.After}}</td></tr>{{end}}</tbody></table></div>{{else}}<p class="muted">Keine Änderungen an Mitgliedschaft oder Reihenfolge.</p>{{end}}
<form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/publish"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Draft.Revision}}"><button {{if or .Validation (eq .Draft.Revision 0) .Draft.Conflicts}}disabled{{end}}>Geprüfte Edition veröffentlichen</button></form><p class="muted">Grund: {{.Draft.Reason}}. Die öffentliche Sichtbarkeit wird in der Sammlungsübersicht eingestellt. Manuelle Änderungen bleiben bei späteren Quellenupdates zur Prüfung erhalten.</p>
<details><summary>Metadaten und gemeinsame Filmzuordnung</summary><form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/metadata"><input type="hidden" name="_csrf" value="{{.CSRF}}"><button>Fehlende / veraltete TMDb-Metadaten laden oder Fehler erneut versuchen</button></form><p class="muted">Dies lädt Metadaten für veröffentlichte Filme. Die Sammlung wird unabhängig von fehlenden Postern oder TMDb-Treffern vollständig angezeigt.</p><form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/mapping"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label>IMDb ID <input name="imdbId" pattern="tt[0-9]{7,10}" required></label><label>TMDb ID <input name="tmdbId" type="number" min="1" required></label><label>Korrekturgrund <input name="reason" required></label><button>Gemeinsame Zuordnung prüfen und korrigieren</button></form><p class="muted">Diese Korrektur gilt für den Film in allen Canons. Vor dem Speichern wird die IMDb-Identität bei TMDb geprüft.</p></details>
{{if .ModuleName}}<details open><summary>Quellenmodul: {{.ModuleName}}</summary><form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/crawl"><input type="hidden" name="_csrf" value="{{.CSRF}}"><input type="hidden" name="revision" value="{{.Draft.Revision}}"><input type="hidden" name="base" value="{{.Draft.BaseEdition}}"><button {{if ne .Draft.Revision 0}}disabled{{end}}>Quelle jetzt als Entwurf einlesen</button></form><p class="muted">{{if ne .Draft.Revision 0}}Zuerst den vorhandenen Entwurf prüfen und veröffentlichen. {{end}}Jeder Abruf bereitet einen Entwurf vor. Manuelle Änderungen bleiben zur Prüfung erhalten.</p></details>{{end}}<details><summary>Quellen-Refresh konfigurieren</summary><form method="post" action="/canons/{{.Draft.Snapshot.Canon.Slug}}/config"><input type="hidden" name="_csrf" value="{{.CSRF}}"><label>Verfahren <select name="policy"><option value="manual" {{if eq .Policy "manual"}}selected{{end}}>Manuell</option><option value="interval" {{if eq .Policy "interval"}}selected{{end}}>Intervall</option><option value="static" {{if eq .Policy "static"}}selected{{end}}>Statisch</option></select></label><label>Intervall in Kalendermonaten <input name="interval" type="number" min="1" max="36" value="{{.Interval}}" required></label><label><input type="checkbox" name="enabled" value="true" {{if .Enabled}}checked{{end}}> Für späteren Scheduler vormerken (Pause / Fortsetzen)</label><button>Konfiguration speichern</button></form><p class="muted">Registrierte Module lassen sich manuell einlesen. Der automatische Scheduler bleibt deaktiviert; Seitenaufrufe starten keine Abrufe.</p></details>
<details><summary>Veröffentlichungshistorie / Wiederherstellen</summary>{{range .History}}<form method="post" action="/canons/{{$.Draft.Snapshot.Canon.Slug}}/restore"><input type="hidden" name="_csrf" value="{{$.CSRF}}"><input type="hidden" name="revision" value="{{$.Draft.Revision}}"><input type="hidden" name="edition" value="{{.ID}}"><span>{{.Label}} · {{.PublishedAt.Format "2006-01-02 15:04 UTC"}}</span> <button>Als neuen Entwurf wiederherstellen</button></form>{{else}}<p>Noch keine veröffentlichte Edition.</p>{{end}}</details>
</main><script>document.getElementById('filter').addEventListener('input',function(){const term=this.value.toLocaleLowerCase();for(const row of document.querySelectorAll('#films tr')){const fields=Array.from(row.querySelectorAll('input')).map(input=>input.value).join(' ');row.hidden=!(row.textContent+' '+fields).toLocaleLowerCase().includes(term)}});</script></body></html>`
